// Only the exact executable and finite host-action runtime pair may omit the
// executable's private action edge. A CLI import is never pruned here.
func websiteDeliveryPrivateMainEdge(packages []listedPackage, module string) bool {
	main, runtime := false, false
	for _, p := range packages {
		main = main || approvedNetworkConnectPackage(checkedSourcePackage{listed: p}, module, "cmd/vsk-labs")
		runtime = runtime || approvedNetworkConnectPackage(checkedSourcePackage{listed: p}, module, "internal/ingressconnector")
	}
	return main && runtime
}

// Only the finite sealed Linux role's native connector edge is private. Its
// other dependencies, and direct portable-client connector imports, stay visible.
func websiteDeliveryDependencyPruning(packages []listedPackage, module string) map[string]bool {
	role, connector := false, false
	for _, p := range packages {
		role = role || approvedNetworkConnectPackage(checkedSourcePackage{listed: p}, module, "internal/linuxrole")
		connector = connector || approvedNetworkConnectPackage(checkedSourcePackage{listed: p}, module, "internal/ingressconnector")
	}
	result := map[string]bool{}
	if role && connector {
		result[module+"/internal/linuxrole->"+module+"/internal/ingressconnector"] = true
	}
	return result
}
